async function stemCachePut(key,stems){const db=await stemCacheDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('stems','readwrite'),store=tx.objectStore('stems');store.put({stems,created:Date.now()},key);const all=store.getAllKeys();all.onsuccess=()=>{const keys=all.result.filter(k=>k!==key);while(keys.length>2)store.delete(keys.shift())};tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error)})}finally{db.close()}}

window.nightmixAudioDiagnostics=()=>{let rms=null;if(analyser){const a=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(a);rms=Math.sqrt(a.reduce((sum,v)=>sum+v*v,0)/a.length)}return {state:ctx?.state||'not-started',sampleRate:ctx?.sampleRate,master:Number($('#master').value),crossfader:Number($('#cross').value),outputRms:rms,decks:decks.map(d=>({deck:d.id,playing:d.playing,position:d.pos,duration:d.duration,stems:!!d.stemBuffers,sharedStems:!!d.stemBuffers&&sharedAudioEnabled()&&d.stemBuffers.every(b=>b.getChannelData(0).buffer instanceof SharedArrayBuffer),stemPCMBytes:d.stemBuffers?.reduce((n,b)=>n+b.length*b.numberOfChannels*4,0)||0,rate:d.rate,pitch:d.pitchShift||0,cues:d.cues.slice(),eq:{low:d.low?.gain.value,mid:d.mid?.gain.value,high:d.high?.gain.value},filterHz:d.filter?.frequency.value,level:d.vol?.gain.value,mix:d.mix?.gain.value}))}};

for(const d of decks){const controls=$$('.stem-control',d.el);controls.forEach(c=>{const mute=$('button',c),original=mute.onclick;mute.onclick=e=>{if(d.soloIndex!=null){controls.forEach((x,i)=>{const b=$('button',x);b.classList.toggle('muted',d.beforeSolo[i]);$('.stem-solo',x)?.classList.remove('on');d.node.port.postMessage({type:'stemGain',index:i,value:b.classList.contains('muted')?0:+$('input',x).value})});d.soloIndex=null}original(e)}});controls.forEach((c,k)=>{const solo=document.createElement('button');solo.className='stem-solo';solo.textContent='SOLO';solo.disabled=!d.stemsReady;solo.setAttribute('aria-label',d.id+' '+stemNames[k]+' 独听');c.insertBefore(solo,$('input',c));solo.onclick=()=>{if(!d.stemsReady)return;const restore=d.soloIndex===k;if(d.soloIndex==null)d.beforeSolo=controls.map(x=>$('button',x).classList.contains('muted'));d.soloIndex=restore?null:k;controls.forEach((x,i)=>{const mute=$('button',x),input=$('input',x);mute.classList.toggle('muted',restore?d.beforeSolo[i]:i!==k);$('.stem-solo',x).classList.toggle('on',!restore&&i===k);d.node.port.postMessage({type:'stemGain',index:i,value:mute.classList.contains('muted')?0:+input.value})})}})}
async function restoreDeckProcessor(d){const old=d.node;old?.port.close();old?.disconnect();for(const name of ['pitchNode','low','mid','high','filter','vol','mix'])d[name]?.disconnect();d.connect();if(d.stemBuffers){postStemBuffers(d,d.stemBuffers)}else if(d.buffer){const channels=Array.from({length:d.buffer.numberOfChannels},(_,i)=>d.buffer.getChannelData(i).slice());d.node.port.postMessage({type:'load',channels},channels.map(a=>a.buffer))}d.send('seek',d.pos||0);d.send('loop',d.loop);d.setRate(d.rate);$$('.stem-control',d.el).forEach((c,i)=>d.node.port.postMessage({type:'stemGain',index:i,value:$('button',c).classList.contains('muted')?0:+$('input',c).value}));d.playing=false;d.paintTransport()}
const resumeSound= recoverSound.onclick;recoverSound.onclick=safe(async()=>{await audio();for(const d of decks)if(d.processorFailed)await restoreDeckProcessor(d);await resumeSound()});

