function wireIndependentRange(el){
 if(el.dataset.liveRange)return;el.dataset.liveRange='true';el.style.touchAction='none';let pointer=null,changed=false;
 const move=e=>{if(el.disabled)return;const r=el.getBoundingClientRect(),vertical=getComputedStyle(el).writingMode.startsWith('vertical');let f=vertical?1-(e.clientY-r.top)/r.height:(e.clientX-r.left)/r.width;f=Math.max(0,Math.min(1,f));const min=Number(el.min),max=Number(el.max),step=Number(el.step)||.001,value=Math.max(min,Math.min(max,min+Math.round(f*(max-min)/step)*step));if(Number(el.value)===value)return;el.value=value;changed=true;el.dispatchEvent(new Event('input',{bubbles:true}))};
 el.addEventListener('pointerdown',e=>{if(el.disabled||pointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();pointer=e.pointerId;changed=false;el.setPointerCapture(pointer);move(e)},{passive:false});
 el.addEventListener('pointermove',e=>{if(e.pointerId!==pointer)return;e.preventDefault();move(e)},{passive:false});
 el.addEventListener('pointerup',e=>{if(e.pointerId!==pointer)return;move(e);pointer=null;if(changed)el.dispatchEvent(new Event('change',{bubbles:true}));if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId)});
 const cancel=e=>{if(e.pointerId===pointer)pointer=null};el.addEventListener('pointercancel',cancel);el.addEventListener('lostpointercapture',cancel)
}
for(const d of decks){const area=document.createElement('div');area.className='tempo-pitch-panel';const speed=$('.pitch',d.el);speed.querySelector('span').textContent='SPEED';area.append(speed);const pitch=document.createElement('div');pitch.className='key-control';pitch.innerHTML=`<label for="key${d.id}">KEY</label><input id="key${d.id}" aria-label="${d.id} 碟音调" type="range" min="-12" max="12" step="1" value="0"><output>0 st</output><button aria-label="${d.id} 音调复位">↺</button>`;area.append(pitch);d.el.insertBefore(area,$('.transport',d.el));const input=$('input',pitch);input.oninput=liveControl(()=>{d.pitchShift=+input.value;liveParam(d.pitchNode.parameters.get('pitchSemitones'),d.pitchShift);$('output',pitch).textContent=(d.pitchShift>0?'+':'')+d.pitchShift+' st'});$('button',pitch).onclick=()=>{input.value=0;input.oninput()};wireIndependentRange(input)}

function fitStage(){const h=Math.floor(Math.min(window.innerHeight,window.visualViewport?.height||window.innerHeight));document.documentElement.style.setProperty('--stage-height',h+'px')}fitStage();window.addEventListener('resize',fitStage);window.visualViewport?.addEventListener('resize',fitStage);window.addEventListener('orientationchange',fitStage);document.addEventListener('fullscreenchange',fitStage);

