// Composited button light feedback; independent pointers may hold separate pads.
const heldLights=new Map();
function flashButton(button,event){if(!button||button.disabled)return;button.dataset.lastLight=String(performance.now());const r=button.getBoundingClientRect(),wave=document.createElement('span');wave.className='tap-ripple';wave.style.left=((event?.clientX??r.left+r.width/2)-r.left)+'px';wave.style.top=((event?.clientY??r.top+r.height/2)-r.top)+'px';for(const old of [...button.querySelectorAll('.tap-ripple')].slice(0,-2))old.remove();button.append(wave);const size=Math.max(r.width,r.height)*.22;const animation=wave.animate([{transform:'translate(-50%,-50%) scale(0)',opacity:.85},{transform:'translate(-50%,-50%) scale('+size+')',opacity:0}],{duration:420,easing:'cubic-bezier(.1,.5,.3,1)'});animation.onfinish=()=>wave.remove()}
document.addEventListener('pointerdown',e=>{const button=e.target.closest?.('button');if(!button||button.disabled)return;heldLights.set(e.pointerId,button);button.classList.add('press-lit');flashButton(button,e)},{capture:true,passive:true});
function releaseButtonLight(e){const button=heldLights.get(e.pointerId);heldLights.delete(e.pointerId);if(button&&![...heldLights.values()].includes(button))button.classList.remove('press-lit')}
document.addEventListener('pointerup',releaseButtonLight,true);document.addEventListener('pointercancel',releaseButtonLight,true);window.addEventListener('blur',()=>{for(const button of heldLights.values())button.classList.remove('press-lit');heldLights.clear()});
document.addEventListener('click',e=>{if(e.detail!==0)return;const button=e.target.closest?.('button');if(!button||performance.now()-Number(button.dataset.lastLight||0)<400)return;flashButton(button);button.classList.add('press-lit');setTimeout(()=>button.classList.remove('press-lit'),160)},true);

// Independent moving light field and intermittent musical pulse.
const stagePulse=document.createElement('div');stagePulse.className='stage-pulse';stagePulse.setAttribute('aria-hidden','true');document.body.append(stagePulse);
const lightModeButton=document.createElement('button');lightModeButton.className='light-mode';lightModeButton.setAttribute('aria-label','切换舞台灯效');bank.prepend(lightModeButton);
let stageMode='beat',stagePulseCount=0,lastStageBeat='',lastStagePulseAt=-Infinity;try{stageMode=localStorage.getItem('nightmix-stage-mode')||'beat'}catch{}if(!['beat','flow','off'].includes(stageMode))stageMode='beat';
function setStageMode(mode){stageMode=mode;document.body.dataset.lightMode=mode;lightModeButton.textContent='灯效·'+({beat:'节奏',flow:'流动',off:'关闭'})[mode];lightModeButton.setAttribute('aria-pressed',String(mode!=='off'));if(mode!=='beat')for(const animation of stagePulse.getAnimations())animation.cancel();try{localStorage.setItem('nightmix-stage-mode',mode)}catch{}}
lightModeButton.onclick=()=>setStageMode(({beat:'flow',flow:'off',off:'beat'})[stageMode]);setStageMode(stageMode);
const pulsePattern=[1,0,0,.42,.75,0,.32,0],reducedStageMotion=matchMedia('(prefers-reduced-motion: reduce)');
function animateStage(now){if(stageMode==='beat'&&!document.hidden&&!reducedStageMotion.matches){const playing=decks.filter(d=>d.playing),active=playing.length===2?decks[+$('#cross').value>.5?1:0]:playing[0],stride=active?Math.max(1,Math.ceil(active.bpm/120)):1,beat=active?Math.floor(active.pos*active.baseBpm/(60*stride)):Math.floor(now/750),key=(active?.id||'idle')+':'+beat;if(key!==lastStageBeat){lastStageBeat=key;const strength=pulsePattern[((beat%8)+8)%8];if(strength&&now-lastStagePulseAt>=500){lastStagePulseAt=now;stagePulseCount++;stagePulse.style.setProperty('--pulse-hue',active?.id==='B'?'#b457ff':'#2beaff');for(const animation of stagePulse.getAnimations())animation.cancel();stagePulse.animate([{opacity:0},{opacity:.13*strength,offset:.12},{opacity:.05*strength,offset:.4},{opacity:0}],{duration:260,easing:'ease-out'})}}}requestAnimationFrame(animateStage)}requestAnimationFrame(animateStage);
window.nightmixLightingDiagnostics=()=>({mode:stageMode,pulses:stagePulseCount,flowAnimation:getComputedStyle(decks[0].el,'::before').animationName,sharedAudio:sharedAudioEnabled(),reducedMotion:reducedStageMotion.matches});

